//! Property tests for the invariants P1-P9 of docs/11 §10.
//!
//! Inputs are generated by exhaustive enumeration over small, structured
//! domains (every DACL of up to two ACEs over an ACE alphabet; every
//! combination of subject, action, attribute, context, policy and PIP
//! configuration listed below). Deterministic — no random generator, no
//! external crate. Source: docs/11 §10 (the invariants), §4 (the layers);
//! hand-made domains; no vector from another implementation.

mod common;

use common::*;
use dtyp::{Ace, SecurityDescriptor};
use pdp::access_check::rights::*;
use pdp::{
    acl_grants, decide, is_write, AccessRequest, Action, ActionMatch, AttrClass, AttrId,
    AuthStrength, ContextMatch, ControlRightId, Decision, DirObjectContext, Effect, Instant, Match,
    ObjClass, Obligation, PolicySnapshot, ReasonCode, ResourceMatch, Right, Rule, RuleId, Subject,
    SubjectMatch, Tier, TimeWindow, TransportSec,
};

// ------------------------------------------------------------ domains ----

/// The ACE alphabet: simple / object ACEs (attribute, property set, control
/// right), allow / deny, two trustees, three masks, with and without
/// INHERIT_ONLY_ACE.
fn ace_alphabet() -> Vec<Ace> {
    let mut out = Vec::new();
    let masks = [
        RIGHT_DS_READ_PROPERTY,
        RIGHT_DS_READ_PROPERTY | RIGHT_DS_WRITE_PROPERTY,
        RIGHT_GENERIC_ALL,
    ];
    for sid in [user(), other_user()] {
        for mask in masks {
            let aces = [
                allow(mask, sid),
                deny(mask, sid),
                allow_obj(mask, Some(attr_in_set()), sid),
                deny_obj(mask, Some(attr_in_set()), sid),
                allow_obj(mask, Some(propset()), sid),
                deny_obj(mask, Some(propset()), sid),
                allow_obj(mask, Some(right_a()), sid),
            ];
            for ace in aces {
                out.push(inherit_only(ace.clone()));
                out.push(ace);
            }
        }
    }
    out
}

/// Every DACL of length 0, 1 or 2 over the alphabet.
fn all_dacls() -> Vec<Vec<Ace>> {
    let alphabet = ace_alphabet();
    let mut out = vec![vec![]];
    for a in &alphabet {
        out.push(vec![a.clone()]);
    }
    for a in &alphabet {
        for b in &alphabet {
            out.push(vec![a.clone(), b.clone()]);
        }
    }
    out
}

/// A smaller set of descriptors for the `decide`-level properties: no DACL,
/// empty DACL, grant-all, deny-all, an unsupported ACE, and a few mixes.
fn some_descriptors() -> Vec<SecurityDescriptor> {
    vec![
        sd_without_dacl(None),
        sd(None, vec![]),
        sd(Some(user()), vec![]),
        sd(None, vec![allow(RIGHT_GENERIC_ALL, group())]),
        sd(
            None,
            vec![
                deny(RIGHT_GENERIC_ALL, user()),
                allow(RIGHT_GENERIC_ALL, user()),
            ],
        ),
        sd(
            None,
            vec![
                unsupported(dtyp::ace_type::ACCESS_ALLOWED_CALLBACK_ACE_TYPE),
                allow(RIGHT_GENERIC_ALL, group()),
            ],
        ),
        sd(
            None,
            vec![
                allow_obj(RIGHT_DS_READ_PROPERTY, Some(propset()), group()),
                allow_obj(RIGHT_DS_CONTROL_ACCESS, Some(right_a()), user()),
            ],
        ),
        sd(None, vec![allow(RIGHT_GENERIC_READ, group())]),
    ]
}

fn every_right() -> Vec<Right> {
    vec![
        Right::Object {
            mask: RIGHT_DS_READ_PROPERTY,
        },
        Right::Object {
            mask: RIGHT_READ_CONTROL | RIGHT_WRITE_DAC,
        },
        Right::Property {
            mask: RIGHT_DS_READ_PROPERTY,
            property_set: Some(plain_set()),
            attribute: attr_in_set(),
        },
        Right::Property {
            mask: RIGHT_DS_WRITE_PROPERTY,
            property_set: None,
            attribute: attr_alone(),
        },
        Right::CreateChild {
            class: class_group(),
        },
        Right::ControlAccess { right: right_a() },
    ]
}

fn subjects() -> Vec<Subject> {
    let mut out = Vec::new();
    for groups in [vec![], vec![group()]] {
        for tier in [Tier::Tier0, Tier::Tier1] {
            for (strength, verified) in [
                (AuthStrength::Kerberos, true),
                (AuthStrength::Unauth, false),
                (AuthStrength::Pkinit, false),
            ] {
                let mut s = subject(user(), &groups, tier);
                s.auth.strength = strength;
                s.auth.ticket_verified = verified;
                out.push(s);
            }
        }
    }
    out
}

fn dir_actions() -> Vec<(Action, Option<dtyp::Guid>)> {
    vec![
        (Action::DirRead, None),
        (Action::DirRead, Some(attr_in_set())),
        (Action::DirRead, Some(attr_alone())),
        (Action::DirWrite, None),
        (Action::DirWrite, Some(attr_alone())),
        (Action::DirList, None),
        (Action::DirDelete, None),
        (Action::DirAddChild(ObjClass(class_group())), None),
        (Action::DirControlRight(ControlRightId(right_a())), None),
        // Malformed: a whole-object action with an attribute.
        (Action::DirList, Some(attr_alone())),
    ]
}

fn transports() -> Vec<TransportSec> {
    vec![
        TransportSec::NONE,
        TransportSec {
            encrypted: true,
            sealed: false,
            channel_bound: false,
        },
        TransportSec {
            encrypted: true,
            sealed: true,
            channel_bound: true,
        },
    ]
}

fn policies() -> Vec<PolicySnapshot> {
    let deny_group = Rule {
        id: RuleId(2),
        effect: Effect::Deny,
        when: Match {
            subject: SubjectMatch::MemberOf(group()),
            ..match_all()
        },
        obligations: vec![Obligation::Audit],
    };
    let allow_reads = Rule {
        id: RuleId(3),
        effect: Effect::Allow,
        when: Match {
            action: ActionMatch::AnyOf(vec![Action::DirRead, Action::DirList]),
            resource: ResourceMatch::DirSubtree { base: parent_dn() },
            ..match_all()
        },
        obligations: vec![Obligation::Audit],
    };
    vec![
        policy(vec![]),
        policy(vec![allow_everything(1)]),
        policy(vec![allow_everything(1), deny_group]),
        policy(vec![allow_reads]),
    ]
}

/// Visit every generated `decide` input. `f` gets the request, the policy
/// and the PIP.
fn for_each_decide_input(mut f: impl FnMut(&AccessRequest, &PolicySnapshot, &MockPip)) {
    let attr_classes = [
        AttrClass::Normal,
        AttrClass::Sensitive {
            control_access_right: ControlRightId(right_a()),
        },
        AttrClass::Secret,
    ];
    let pols = policies();
    for descriptor in some_descriptors() {
        for object_tier in [Tier::Tier0, Tier::Tier1] {
            for class in attr_classes {
                for pip_tier in [Tier::Tier0, Tier::Tier1] {
                    let mut pip = MockPip::with_sd(descriptor.clone());
                    pip.object_tiers.insert(obj_dn(), object_tier);
                    pip.attr_classes.insert(AttrId(attr_alone()), class);
                    pip.attr_classes.insert(AttrId(attr_in_set()), class);
                    pip.tiers.insert(user(), pip_tier);
                    for s in subjects() {
                        for (action, attr) in dir_actions() {
                            for sec in transports() {
                                let mut req = dir_request(s.clone(), action.clone(), attr);
                                req.context.transport_sec = sec;
                                for pol in &pols {
                                    f(&req, pol, &pip);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

fn object() -> DirObjectContext {
    DirObjectContext {
        object_class: class_user(),
        superclasses: vec![],
        object_sid: Some(user()),
    }
}

// ----------------------------------------------------------- P1, P7 ----

/// P1 (decide is total and deterministic: same input, same answer, never a
/// panic) and P7 (every decision carries exactly one Audit obligation), plus
/// the shape of a decision: Allow ⇔ reason `Allowed`.
#[test]
fn p1_p7_decide_is_total_deterministic_and_audited() {
    let mut count = 0usize;
    let mut reasons = std::collections::BTreeMap::<ReasonCode, usize>::new();
    for_each_decide_input(|req, pol, pip| {
        let first = decide(req, pol, pip);
        let second = decide(req, pol, pip);
        assert_eq!(first, second, "P1: not deterministic for {req:?}");
        assert!(exactly_one_audit(&first), "P7: {first:?}");
        assert_eq!(
            first.effect == Effect::Allow,
            first.reason == ReasonCode::Allowed,
            "decision shape: {first:?}"
        );
        *reasons.entry(first.reason).or_default() += 1;
        count += 1;
    });
    assert!(count > 100_000, "domain too small: {count}");
    // The domain reaches every layer: each of these outcomes occurs.
    for reason in [
        ReasonCode::Allowed,
        ReasonCode::InvalidRequest,
        ReasonCode::Unauthenticated,
        ReasonCode::WeakTransport,
        ReasonCode::SubjectMismatch,
        ReasonCode::CoarseDeny(RuleId(2)),
        ReasonCode::NoGrant,
        ReasonCode::TierViolation,
        ReasonCode::Acl,
        ReasonCode::NoSuchPath,
        ReasonCode::Sensitive,
    ] {
        assert!(
            reasons.get(&reason).copied().unwrap_or(0) > 0,
            "outcome never reached: {reason:?} ({reasons:?})"
        );
    }
}

/// P1 for the ACL check alone: `acl_grants` is total and deterministic over
/// every DACL of up to two ACEs, every owner and every kind of right.
#[test]
fn p1_acl_grants_is_total_and_deterministic() {
    let s = the_user();
    let o = object();
    for aces in all_dacls() {
        for owner in [None, Some(user()), Some(other_user())] {
            let d = sd(owner, aces.clone());
            for right in every_right() {
                assert_eq!(
                    acl_grants(&s, &d, &o, &right),
                    acl_grants(&s, &d, &o, &right)
                );
            }
        }
    }
}

// ---------------------------------------------------------------- P2 ----

/// P2 (deny by default): with no rules nothing is allowed; and nothing on a
/// directory object is allowed unless the ACL grants the desired right.
#[test]
fn p2_default_deny() {
    for_each_decide_input(|req, pol, pip| {
        let d = decide(req, pol, pip);
        if pol.rules().is_empty() {
            assert_eq!(d.effect, Effect::Deny, "P2: no rule, yet {d:?}");
        }
        if d.effect == Effect::Allow {
            // An Allow rule matched (layer 3)...
            assert!(
                pol.rules()
                    .iter()
                    .any(|r| r.effect == Effect::Allow && r.when.matches(req)),
                "P2: allowed without a matching Allow rule"
            );
            // ...and the descriptor has a DACL (rule 5a) with at least one ACE.
            let descriptor = pip.sds.get(&obj_dn()).expect("known object");
            assert!(
                descriptor.dacl.as_ref().is_some_and(|d| !d.aces.is_empty()),
                "P2: allowed through an absent or empty DACL: {req:?}"
            );
        }
    });
}

/// P2 for the ACL check: an empty DACL grants a non-owner nothing, and no
/// DACL (rule 5a) grants nothing to anyone.
#[test]
fn p2_acl_default_deny() {
    let o = object();
    for s in subjects() {
        for right in every_right() {
            assert!(!acl_grants(&s, &sd(Some(other_user()), vec![]), &o, &right));
            for owner in [None, Some(user()), Some(other_user())] {
                assert!(!acl_grants(&s, &sd_without_dacl(owner), &o, &right));
            }
        }
    }
}

// ---------------------------------------------------------------- P3 ----

/// P3 (no Subject field is client-claimed): whenever the request's tier
/// differs from the PIP's, the decision is Deny.
#[test]
fn p3_tier_not_claimable() {
    for_each_decide_input(|req, pol, pip| {
        let pip_tier = pip.tiers.get(&req.subject.principal).copied();
        if pip_tier != Some(req.subject.tier) {
            assert_eq!(decide(req, pol, pip).effect, Effect::Deny, "P3: {req:?}");
        }
    });
}

// ---------------------------------------------------------------- P4 ----

/// P4 (an explicit Deny at any layer ⇒ Deny), layer 3: adding a matching
/// Deny rule — first or last — to any policy makes every decision Deny.
#[test]
fn p4_explicit_deny_rule_wins() {
    let deny_all = Rule {
        id: RuleId(99),
        effect: Effect::Deny,
        when: match_all(),
        obligations: vec![],
    };
    for_each_decide_input(|req, pol, pip| {
        let mut first = vec![deny_all.clone()];
        first.extend(pol.rules().iter().cloned());
        let mut last: Vec<Rule> = pol.rules().to_vec();
        last.push(deny_all.clone());
        for rules in [first, last] {
            let d = decide(req, &policy(rules), pip);
            assert_eq!(d.effect, Effect::Deny, "P4: {req:?}");
        }
    });
}

/// P4, layer 5: a deny ACE for the requester's own SID at the head of any
/// DACL denies the requested right (owners drawn from {none, the requester,
/// someone else}, so no owner-implied right is left — [MS-DTYP] 2.5.3.2,
/// Q-050).
#[test]
fn p4_explicit_deny_ace_wins() {
    let s = the_user();
    let o = object();
    for aces in all_dacls() {
        for owner in [None, Some(user()), Some(other_user())] {
            for right in every_right() {
                let mask = match right {
                    Right::Object { mask } | Right::Property { mask, .. } => mask,
                    Right::CreateChild { .. } => RIGHT_DS_CREATE_CHILD,
                    Right::ControlAccess { .. } => RIGHT_DS_CONTROL_ACCESS,
                };
                let mut with_deny = vec![deny(mask, user())];
                with_deny.extend(aces.iter().cloned());
                assert!(
                    !acl_grants(&s, &sd(owner, with_deny), &o, &right),
                    "P4: {right:?} {aces:?}"
                );
            }
        }
    }
}

// ---------------------------------------------------------------- P5 ----

/// P5 (the tier invariant holds independently of the ACL): a write to a
/// Tier-0 object by a non-Tier-0 subject is denied for every descriptor —
/// including grant-all and absent-DACL ones — and every policy; when layers
/// 1-3 pass, the reason is the tier violation itself.
#[test]
fn p5_tier_invariant_independent_of_acl() {
    let mut descriptors = some_descriptors();
    for aces in all_dacls().into_iter().step_by(97) {
        descriptors.push(sd(None, aces));
    }
    for descriptor in descriptors {
        let mut pip = MockPip::with_sd(descriptor);
        pip.object_tiers.insert(obj_dn(), Tier::Tier0);
        for (action, attr) in dir_actions() {
            if !is_write(&action) {
                continue;
            }
            for pol in policies() {
                let req = dir_request(the_user(), action.clone(), attr);
                let d = decide(&req, &pol, &pip);
                assert_eq!(d.effect, Effect::Deny, "P5: {req:?}");
                // Under the Allow-all policy layers 1-3 pass (authenticated
                // Tier-1 subject, full transport), so layer 4 is what denies.
                if pol == policy(vec![allow_everything(1)]) {
                    assert_eq!(d.reason, ReasonCode::TierViolation, "P5: {req:?}");
                }
            }
        }
    }
}

// ---------------------------------------------------------------- P6 ----

/// P6 (a Secret attribute is unreachable): every request naming a Secret
/// attribute is denied, for every descriptor, subject, tier, transport and
/// policy.
#[test]
fn p6_secret_unreachable() {
    for_each_decide_input(|req, pol, pip| {
        if let pdp::Resource::DirObject { attr: Some(a), .. } = &req.resource {
            if pip.attr_classes.get(a) == Some(&AttrClass::Secret) {
                assert_eq!(decide(req, pol, pip).effect, Effect::Deny, "P6: {req:?}");
            }
        }
    });
}

// ---------------------------------------------------------------- P8 ----

/// P8 (deny-widening is visible within a bounded time; errors fail closed):
/// the core is stateless, so a policy or descriptor change that removes a
/// grant is effective on the very next call.
#[test]
fn p8_revocation_is_immediate() {
    let req = dir_request(the_user(), Action::DirRead, Some(attr_alone()));
    let granting = MockPip::with_sd(sd(None, vec![allow(RIGHT_GENERIC_READ, user())]));
    let v1 = policy(vec![allow_everything(1)]);
    assert_eq!(decide(&req, &v1, &granting).effect, Effect::Allow);

    // Policy change: a Deny rule in the next snapshot.
    let mut rules = v1.rules().to_vec();
    rules.push(Rule {
        id: RuleId(5),
        effect: Effect::Deny,
        when: match_all(),
        obligations: vec![],
    });
    assert_eq!(decide(&req, &policy(rules), &granting).effect, Effect::Deny);

    // Directory change: the grant removed from the descriptor.
    let revoked = MockPip::with_sd(sd(None, vec![]));
    assert_eq!(decide(&req, &v1, &revoked).effect, Effect::Deny);

    // And back: nothing was remembered.
    assert_eq!(decide(&req, &v1, &granting).effect, Effect::Allow);
}

// ---------------------------------------------------------------- P9 ----

/// P9 (no dependence on clock non-determinism beyond the explicit
/// `Context.time`): without time-window rules, decisions do not depend on
/// `Context.time` at all; with one, they depend only on it.
#[test]
fn p9_no_clock_dependence() {
    let times = [Instant(0), Instant(1_700_000_000), Instant(u64::MAX)];
    for_each_decide_input(|req, pol, pip| {
        let reference = decide(req, pol, pip);
        for t in times {
            let mut at = req.clone();
            at.context.time = t;
            // A different ticket age does not matter either.
            at.subject.auth.ticket_age = core::time::Duration::from_secs(u64::from(t.0 as u32));
            assert_eq!(decide(&at, pol, pip), reference, "P9: {req:?}");
        }
    });

    // With a window: a function of Context.time only.
    let window = TimeWindow::new(Instant(100), Instant(200)).expect("ordered");
    let timed = policy(vec![Rule {
        id: RuleId(1),
        effect: Effect::Allow,
        when: Match {
            context: ContextMatch {
                time_window: Some(window),
                ..ContextMatch::ANY
            },
            ..match_all()
        },
        obligations: vec![],
    }]);
    let pip = MockPip::with_sd(sd(None, vec![allow(RIGHT_GENERIC_READ, user())]));
    let mut req = dir_request(the_user(), Action::DirRead, Some(attr_alone()));
    let mut decisions: Vec<(u64, Decision)> = Vec::new();
    for t in [99u64, 100, 150, 200, 201] {
        req.context.time = Instant(t);
        decisions.push((t, decide(&req, &timed, &pip)));
    }
    for (t, d) in &decisions {
        let inside = (100..=200).contains(t);
        assert_eq!(d.effect == Effect::Allow, inside, "P9 window at {t}");
        req.context.time = Instant(*t);
        assert_eq!(&decide(&req, &timed, &pip), d);
    }
}

// ------------------------------------------------- A-28 never widens ----

/// The ACE alphabet of `a28_never_grants_more_than_before`: the base
/// alphabet plus allow / deny object ACEs naming each class of the chains
/// (most specific, superclass, a class in no chain is `class_group`, already
/// a child class) and both GUIDs of the shared property set.
fn a28_alphabet() -> Vec<Ace> {
    let mut out = ace_alphabet();
    let masks = [
        RIGHT_DS_READ_PROPERTY,
        RIGHT_DS_READ_PROPERTY | RIGHT_DS_WRITE_PROPERTY,
        RIGHT_GENERIC_ALL,
    ];
    for mask in masks {
        for g in [
            class_user(),
            class_computer(),
            class_top(),
            shared_guid(),
            attr_in_shared_set(),
        ] {
            for ace in [
                allow_obj(mask, Some(g), user()),
                deny_obj(mask, Some(g), user()),
            ] {
                out.push(inherit_only(ace.clone()));
                out.push(ace);
            }
        }
    }
    out
}

/// The objects: the default one (`class_user`, no other class listed) and a
/// `class_computer` with its superclass chain.
fn a28_objects() -> Vec<DirObjectContext> {
    vec![
        object(),
        DirObjectContext {
            object_class: class_computer(),
            superclasses: vec![class_top(), class_person(), class_user()],
            object_sid: Some(user()),
        },
    ]
}

/// Every right of `every_right()`, plus the requests A-28 is about: the
/// attribute whose GUID is its own property set's, another member of that
/// set, a child of the object's own class and a child of `class_user`
/// (a superclass of the computer; the object's own class for the user).
fn a28_rights(o: &DirObjectContext) -> Vec<Right> {
    let mut out = every_right();
    out.extend([
        Right::Property {
            mask: RIGHT_DS_READ_PROPERTY,
            property_set: Some(shared_set()),
            attribute: shared_guid(),
        },
        Right::Property {
            mask: RIGHT_DS_WRITE_PROPERTY,
            property_set: Some(shared_set()),
            attribute: shared_guid(),
        },
        Right::Property {
            mask: RIGHT_DS_READ_PROPERTY,
            property_set: Some(shared_set()),
            attribute: attr_in_shared_set(),
        },
        Right::CreateChild {
            class: o.object_class,
        },
        Right::CreateChild {
            class: class_user(),
        },
    ]);
    out
}

/// The request as the object type tree before A-28 saw it, so that
/// `acl_grants` on it gives the pre-A-28 result:
/// - the root was labelled by the most specific class only (the PIP gave
///   no other class): `superclasses` is emptied;
/// - nothing marked a property set GUID as an attribute's:
///   `is_attribute_guid` is cleared;
/// - every object ACE was located at the shallowest node carrying its GUID,
///   so a lower node with the same GUID as a higher one was never located
///   itself and was reached by exactly the ACEs that reached the higher
///   node. It behaved as the higher node (an attribute below its own
///   property set: the set node is dropped) or as a node no ACE names (a
///   child class equal to the object's class: replaced by `guid(0x7F)`,
///   outside every alphabet).
///
/// Checked once against the pre-change build over this test's domain
/// (459,382 cases with owner `None`): identical results.
fn pre_a28(o: &DirObjectContext, right: &Right) -> (DirObjectContext, Right) {
    let object = DirObjectContext {
        superclasses: Vec::new(),
        ..o.clone()
    };
    let unnamed = guid(0x7F);
    let right = match *right {
        Right::Property {
            mask,
            property_set: Some(set),
            attribute,
        } if set.guid == attribute => Right::Property {
            mask,
            property_set: None,
            attribute,
        },
        Right::Property {
            mask,
            property_set: Some(set),
            attribute,
        } => Right::Property {
            mask,
            property_set: Some(pdp::PropertySet {
                guid: set.guid,
                is_attribute_guid: false,
            }),
            attribute,
        },
        Right::CreateChild { class } if class == o.object_class => {
            Right::CreateChild { class: unnamed }
        }
        Right::ControlAccess { right } if right == o.object_class => {
            Right::ControlAccess { right: unnamed }
        }
        other => other,
    };
    (object, right)
}

/// A-28 (Q-081) item 3: neither rule ever grants more than the object type
/// tree without it. Over every DACL of up to two ACEs (base alphabet plus
/// class-typed and shared-GUID object ACEs), both objects, two owners and
/// every right: A-28 grants ⇒ the pre-A-28 tree grants. The domain also
/// reaches a strictly stricter result for each rule, so the check is not
/// vacuous. Source: A-28 (Q-081); [MS-ADTS] 5.1.3.3.3; the invariant stated
/// in `access_check`'s module documentation.
#[test]
fn a28_never_grants_more_than_before() {
    let s = the_user();
    let mut checked = 0usize;
    // Strictly stricter results: superclass (computer object), shared GUID
    // outside the chain (other member), shared GUID inside the chain (the
    // attribute itself), child of the object's own class.
    let (mut superclass, mut other_member, mut in_chain, mut own_child) = (0, 0, 0, 0);
    let alphabet = a28_alphabet();
    let mut dacls = vec![vec![]];
    dacls.extend(alphabet.iter().map(|a| vec![a.clone()]));
    for a in &alphabet {
        for b in &alphabet {
            dacls.push(vec![a.clone(), b.clone()]);
        }
    }
    for aces in &dacls {
        for owner in [None, Some(user())] {
            let d = sd(owner, aces.clone());
            for o in a28_objects() {
                for right in a28_rights(&o) {
                    let (old_object, old_right) = pre_a28(&o, &right);
                    let now = acl_grants(&s, &d, &o, &right);
                    let before = acl_grants(&s, &d, &old_object, &old_right);
                    assert!(
                        !now || before,
                        "A-28 widened a grant: {right:?} on {o:?} with {aces:?}, owner {owner:?}"
                    );
                    if before && !now {
                        // Attribute each stricter result to one rule: rule 1
                        // alone on the computer for the rights of
                        // `every_right()` (no duplicate GUID involved), rule
                        // 2 alone on the user object (no superclass listed).
                        let duplicate = match right {
                            Right::Property {
                                property_set: Some(set),
                                attribute,
                                ..
                            } if set.is_attribute_guid => Some(if set.guid == attribute {
                                &mut in_chain
                            } else {
                                &mut other_member
                            }),
                            Right::CreateChild { class } if class == o.object_class => {
                                Some(&mut own_child)
                            }
                            _ => None,
                        };
                        match (o.superclasses.is_empty(), duplicate) {
                            (true, Some(count)) => *count += 1,
                            (false, None) if every_right().contains(&right) => superclass += 1,
                            _ => {}
                        }
                    }
                    checked += 1;
                }
            }
        }
    }
    assert!(checked > 900_000, "domain too small: {checked}");
    for (rule, count) in [
        ("superclass deny", superclass),
        ("shared GUID, other member", other_member),
        ("shared GUID, the attribute", in_chain),
        ("child of the object's own class", own_child),
    ] {
        assert!(count > 0, "never stricter than before: {rule}");
    }
}

// ------------------------------------------------------- layer 2 table ----

/// Layer 2 follows `required_sec` exactly, for every action (A-22): with an
/// authenticated subject, an Allow-all policy and a transport with no
/// protection, the decision is `WeakTransport` if and only if the action has
/// a floor — so DnsUpdate and the Kdc* actions are never refused for their
/// transport, and every other action is.
#[test]
fn layer2_follows_required_sec_for_every_action() {
    use pdp::{KerbResKind, PolicyScope, Resource, ShareId, Spn, ZoneId};
    let dir = |attr: Option<dtyp::Guid>| Resource::DirObject {
        dn: obj_dn(),
        attr: attr.map(AttrId),
    };
    let dns = Resource::Dns {
        zone: ZoneId("test".into()),
        record: None,
    };
    let kerberos = Resource::Kerberos {
        kind: KerbResKind::Service(Spn("ldap/dc1.test".into())),
    };
    let file = Resource::File {
        share: ShareId("sysvol".into()),
        path: pdp::FilePath(vec!["a".into()]),
    };
    let cases = vec![
        (Action::DirRead, dir(Some(attr_alone()))),
        (Action::DirWrite, dir(Some(attr_alone()))),
        (Action::DirAddChild(ObjClass(class_group())), dir(None)),
        (Action::DirDelete, dir(None)),
        (Action::DirList, dir(None)),
        (
            Action::DirControlRight(ControlRightId(right_a())),
            dir(None),
        ),
        (
            Action::RpcCall,
            Resource::RpcMethod {
                iface: guid(0x66),
                opnum: 0,
            },
        ),
        (Action::FileRead, file.clone()),
        (Action::FileWrite, file),
        (Action::DnsUpdate, dns.clone()),
        (Action::DnsXfer, dns),
        (Action::KdcAs, kerberos.clone()),
        (Action::KdcTgs, kerberos.clone()),
        (Action::KdcS4u2Self, kerberos.clone()),
        (Action::KdcS4u2Proxy, kerberos),
        (
            Action::PolicyAdmin,
            Resource::Policy {
                scope: PolicyScope("domain".into()),
            },
        ),
    ];
    let pip = MockPip::with_sd(sd(None, vec![allow(RIGHT_GENERIC_ALL, group())]));
    let pol = policy(vec![allow_everything(1)]);
    for (action, resource) in cases {
        let mut req = AccessRequest {
            subject: the_user(),
            resource,
            action: action.clone(),
            context: strong_context(),
        };
        req.context.transport_sec = TransportSec::NONE;
        let has_floor = pdp::required_sec(&action) != TransportSec::NONE;
        let d = decide(&req, &pol, &pip);
        assert_eq!(
            d.reason == ReasonCode::WeakTransport,
            has_floor,
            "{action:?}: {d:?}"
        );
        if !has_floor {
            assert_eq!(d.effect, Effect::Allow, "{action:?}: {d:?}");
        }
    }
}
